ces|戰後惡性通貨膨脹|美援在新臺幣發行之後才開始；耕者有其田與加工出口區都是後來的政策；都不是發行新臺幣的原因|發行新臺幣是為了穩定飆漲的物價；銀元不是唯一通用貨幣；外資大量湧入是後來加工出口區時期的事
ces|土地改革|加工出口區、九年國教、六年國建都與土地分配無關|地主的超額土地被徵收，沒有取得更多土地；佃農變成自耕農而減少；農業生產反而提高
ces|第一次石油危機|三七五減租是戰後初期；亞洲金融風暴是一九九七年；全民健保是一九九五年；都不是十大建設的原因|政府加速公共建設而非暫停；臺灣仍以工業為主；石油危機時油價上漲
ces|工資與土地成本上升|三七五減租、設立證券交易所、六年國建都不是產業外移的原因|成本上升使勞力密集產業移出而非移入；紡織業比重下降；家庭代工式的「客廳即工廠」逐漸減少
ces|實施九年國民義務教育|開放外籍勞工、耕者有其田、證券交易所都不是勞動力素質提升的原因|教育提升使農業人口比例下降；大學聯考很久以後才改為多元入學；十二年國教是二〇一四年才實施
ces|晚婚、不婚與育兒成本提高|平均壽命延長造成的是高齡化；外籍勞工補充勞力；全民健保是醫療制度；都不是少子化的主要原因|少子化使幼年人口比例減少、小學班級數減少，人口金字塔底部變窄
ces|美援提供資金與物資|產業升級、新竹科學園區、開放觀光都是很久以後的事|美援使物價逐漸穩定、基礎建設推進；臺灣當時是受援國，不是援助他國
ces|加工出口區提供免稅優惠|推動自由化國際化、加入世界貿易組織、十二項建設都在加工出口區設立之後|外資進入而非撤出；臺灣改以工業產品出口為主；就業增加使工資逐漸上升
ces|醫療進步與少子化|產業升級、自由化國際化、十二項建設都不是本題人口老化的主要直接原因|醫療進步與少子化使人口老化，老年人口比例上升、幼年人口比例下降
cnh1|秦朝施行嚴刑峻法、賦役沉重|商鞅變法發生在秦統一以前，使秦國富強；王莽篡漢、光武帝中興都是漢代的事；都不是秦朝滅亡的原因|秦朝只維持十多年就滅亡；六國貴族多起兵反秦；秦朝推行郡縣制，並未改行分封
cnh1|東漢末年政治腐敗、爆發黃巾之亂|北魏孝文帝漢化、隋煬帝開鑿大運河、唐太宗貞觀之治都發生在三國之後|隋朝統一南北是三國之後很久的事；漢末國勢衰敗而非鼎盛；北魏統一北方是南北朝時期
cnh1|安史之亂|郡縣制度、休養生息、察舉制度都是秦漢時期的制度與政策，不是唐朝由盛轉衰的原因|安史之亂後唐朝國勢衰落，不再是最高峰；在西域的勢力反而退縮；中央權力被藩鎮削弱
cnh1|隋朝開創科舉制度|武則天雖然重視科舉，但讓寒門有機會考試做官的根本是隋朝開創的科舉；府兵制是兵制；鹽鐵專賣是漢代的財政政策|科舉依考試選官，不是世襲；不再全由地方推薦；寒門子弟也能應考，不是只有貴族
cnh1|西晉末年北方戰亂、晉室南遷|秦朝統一文字與度量衡、漢朝推恩令都是更早的事；隋文帝統一南北在南遷之後；都不是人口南移的原因|北方戰亂使人口減少而非增加；江南因人口移入而開發，不是荒廢；江南經濟逐漸追上北方
cnh1|漢武帝獨尊儒術|商鞅變法屬於法家；王莽篡漢、光武帝中興都在獨尊儒術之後；都不是儒家成為正統的原因|成為正統的是儒家，不是道家；百家爭鳴是春秋戰國的現象，獨尊儒術後反而衰微；科舉以儒家經典為主要內容
cnh1|唐中葉均田制崩壞|北魏孝文帝漢化、隋煬帝開鑿大運河、唐太宗貞觀之治都不是唐中葉改行兩稅法的原因|井田制是周代的制度；一條鞭法是明代的稅制；兩稅法依財產與土地課稅，並非恢復秦朝制度
cnh1|周天子權威衰落|武則天稱帝、秦朝郡縣制度、漢初休養生息都在春秋戰國之後|周天子權威衰落，周朝國勢衰弱；諸侯分立而非統一；封建制度逐漸瓦解
cnh2|張騫出使西域|班超經營西域是東漢的事，在張騫之後；鹽鐵專賣是財政政策；蔡倫改良造紙是東漢的技術；都不是絲路開通的原因|遣唐使是唐代的事；鄭和下西洋是明代；佛教傳入日本是後來東亞文化交流的結果，不是張騫出使直接造成的
cnh2|蒙古帝國廣設驛站|和親是漢代對匈奴的政策；鄭和下西洋是明代；鑑真東渡是唐代；都不是元代歐亞交通暢通的原因|驛站使交通更暢通，而非中斷；陸上絲路在元代反而活絡；海禁是明朝的政策
cnh2|指南針應用於航海|玄奘西行走的是陸路；馬可波羅、利瑪竇是來華的人物；都不是遠洋航行便利的原因|海上貿易地位提高，不是被陸上交通取代；宋朝鼓勵海外貿易，並未禁止造船；指南針使航行更安全
cnh2|遣隋使、遣唐使與留學生帶回隋唐制度|市舶司管理海外貿易；明朝海禁限制對外往來；班超經營西域；都不是大化革新參考隋唐制度的原因。大化革新的直接契機是中大兄皇子等人推翻蘇我氏，而改革的制度則是透過遣隋使、遣唐使與留學生學來的|明治維新是十九世紀學習西方的改革；日本使用漢字並發展出假名，沒有改用拼音文字；大化革新加強天皇的中央集權，並未廢除天皇
cnh2|魏晉南北朝戰亂頻繁|澶淵之盟是宋代；元朝設立行省是元代；長安成為國際都市是唐代；都不是魏晉佛教流行的原因|道教並非唯一的官方宗教；戰亂時期儒學衰微，佛教成為心靈寄託；基督教當時尚未在中國流傳
cnh2|造紙術經阿拉伯人西傳|法顯赴天竺求法是佛教交流；活字印刷是北宋的發明；鄭和下西洋是明代航海；都不是歐洲書寫便利的原因|歐洲並未改用竹簡；紙張普及使知識傳播更容易，識字人口不會因此減少；紙張傳入後逐漸成為歐洲重要的書寫材料，並沒有被禁止
cnh2|宋代北方政權阻隔陸路，加上航海技術進步|漢朝和親、鑑真東渡、玄奘西行都不是宋代海上貿易地位提高的原因|陸上絲路受阻而衰落；宋朝反而建造更多海船；宋朝設市舶司鼓勵海上貿易，並未禁止
cnh3|唐末五代武人專政|王安石變法是宋朝中期的事；衛所制、一條鞭法是明代制度；都不是宋朝重文輕武的原因|宋朝壓抑武將，武將地位沒有提高；節度使的兵權被收回；地方軍閥割據受到抑制
cnh3|宋朝重文輕武|軍機處、文字獄是清代的事；明成祖遷都北京是明代；都不是宋朝國防較弱的原因|宋朝未能收復燕雲十六州；宋朝向遼、西夏等納歲幣，不是對方向宋稱臣；武將受到壓抑，沒有掌握中央大權
cnh3|明太祖廢除宰相|杯酒釋兵權是宋初；平定三藩、收復臺灣是清初；都不是明朝皇權集中的原因|宰相被廢除，權力不會大增；內閣只是皇帝的顧問，不能限制皇權；藩鎮割據是唐代後期的現象
cnh3|明清實施海禁|明清各時期的海禁寬嚴不同；理學是思想；元朝開通南北海運是交通；內閣是政治制度；都不是走私與海盜增加的原因|海禁使官方與合法貿易受限；倭寇問題反而加劇；朝廷禁止民間出海，並未鼓勵造船
cnh3|宋代科舉擴大錄取並防止舞弊|元朝設立行省是地方制度；鄭和下西洋是明代航海；王安石變法是財政與軍事改革；都不是平民入仕增加的原因|科舉使平民也能做官，不是只有貴族；宋朝沒有廢除科舉；宋朝重文輕武，文官地位高於武將
cnh3|江南農業與手工業發達|杯酒釋兵權、衛所制、軍機處都是軍事或政治制度，不是江南商品經濟繁榮的原因|江南人口密集而非外移；市鎮興起而非沒落；商品經濟繁榮而非衰退
cnh3|元朝實施四等人制|一條鞭法是明代稅制；文字獄是清代；遷都北京是明代；都不是元代族群不平等的原因|四等人制使各族群地位不平等；蒙古人地位最高，漢人、南人地位較低；科舉時辦時停，且對漢人不利
cnh3|清朝限定一口通商|平定三藩、收復臺灣是清初的軍事行動；理學是宋代思想；都不是中西貿易受限的原因|一口通商使貿易受限而非開放；英國想擴大貿易，沒有停止來華；中國並未主動派商船到英國
cnh4|清朝查禁鴉片|英法聯軍攻入北京、設立總理衙門、興辦江南製造局都發生在鴉片戰爭之後|戰後簽訂的是不平等的南京條約，不是友好條約；英國沒有禁止鴉片出口；英國也沒有撤出廣州
cnh4|鴉片戰爭清朝戰敗|中法戰爭、左宗棠收復新疆、劉銘傳在臺建省都在鴉片戰爭之後|馬關條約是甲午戰爭後簽訂的；英國擴大在中國的貿易，沒有退出；戊戌變法在甲午戰爭之後
cnh4|太平天國動亂|虎門銷煙是鴉片戰爭的導火線；留美幼童是自強運動；垂簾聽政是宮廷政治；都不是地方督撫崛起的原因|太平天國後中央權力減弱、地方督撫權力擴大；湘軍、淮軍取代八旗成為主力
cnh4|甲午戰爭清朝戰敗|廢除科舉、日俄戰爭、京師大學堂成立都在甲午戰爭之後|清朝戰敗後承認朝鮮獨立，沒有取得朝鮮；南京條約是鴉片戰爭後簽訂的；帝制到辛亥革命後才結束
cnh4|守舊勢力反對變法|天津條約、英法聯軍攻入北京、設立總理衙門都在戊戌變法之前，不是變法失敗的原因|變法失敗，沒有成功推行；光緒皇帝被軟禁，慈禧太后掌權；君主立憲沒有實現
cnh4|清廷縱容義和團攻擊使館|虎門銷煙、江南製造局、中法戰爭都在義和團事件之前|列強攻入北京而非撤出；清朝簽訂辛丑和約，沒有收回租界；義和團被鎮壓，沒有成為正規軍
cnh4|清廷成立皇族內閣|左宗棠收復新疆、劉銘傳在臺建省、派遣留美幼童都是較早的事，不是立憲派轉向的原因|部分立憲人士轉而支持革命，而不是更支持清廷；革命黨沒有解散；皇族內閣使權力集中於皇族，國會沒有實權
cnh4|自強運動未改革政治制度|廢除科舉、日俄戰爭、京師大學堂成立都在自強運動之後，不是成效有限的原因|中國並未成為亞洲最強的國家；北洋艦隊在甲午戰爭中敗給日本；自強運動沒有改革政治，也未實施君主立憲
cnh5|武昌起義後各省響應|日本提出二十一條要求、新文化運動、中國共產黨成立都在民國成立之後|袁世凱後來稱帝失敗；清朝並未實施君主立憲；國共合作是一九二〇年代的事
cnh5|袁世凱企圖稱帝|國民政府定都南京、黃埔軍校成立、中原大戰都在袁世凱死後|袁世凱稱帝失敗，不久去世；清朝沒有恢復統治；北伐是一九二〇年代後期的事
cnh5|巴黎和會將山東權益轉給日本|張勳復辟是另一個事件；東北易幟、新生活運動都在五四運動之後|中國沒有取得山東權益；中國參加一戰是在和會之前；軍閥並未解散
cnh5|軍閥割據|中國參加一戰、宋教仁遇刺都是民國初年的事；汪精衛成立政權是抗戰時期；都不是北伐的原因|袁世凱稱帝、張勳復辟都失敗了；日本並未退出東北
cnh5|九一八事變|中共長征、國民政府實施訓政都是國內的事；二十一條要求是更早的事；都不是日本占領東北的直接原因|中國到抗戰勝利後才收回東北；日本歸還臺灣是二戰結束後；香港到一九九七年才回歸
cnh5|西安事變|新文化運動、國民政府定都南京、黃埔軍校成立都在西安事變之前很久|西安事變促成國共停止內戰、合作抗日，而非決裂；日本沒有撤出東北；山東權益在一九二〇年代初就已收回，與西安事變無直接關係
cnh5|七七事變|中國共產黨成立、中原大戰、中國參加一戰都在七七事變之前|中日沒有簽訂和約，而是全面開戰；日本沒有撤出東北；國共第二次合作抗日，內戰到戰後才全面爆發
cnh5|國共內戰國民政府失利|張勳復辟、東北易幟、新生活運動都在國共內戰之前|國民政府失去大陸，沒有統一中國；國民政府遷往臺灣，而非遷都南京；取得大陸政權的是共產黨
cnh6|大躍進不切實際的生產目標|中共加入聯合國是一九七一年；中蘇交惡是外交關係的變化；香港回歸是一九九七年；都不是大饑荒的原因|大躍進導致糧食短缺，而非大豐收；工業產量並未超越英國；農民生活更加困苦
cnh6|文化大革命|人民公社在文革之前；一胎化政策在文革之後；六四事件在一九八九年；都不是文革期間教育文化遭破壞的原因|文革中知識分子受到迫害，地位沒有提高；教育中斷而非普及；傳統文化遭到破壞
cnh6|改革開放引進市場機制|人民公社、大躍進是改革開放以前的計畫經濟做法；中蘇交惡是外交；都不是經濟快速成長的原因|改革開放後經濟快速成長，不是停滯；中國擴大國際貿易；人民公社被廢除
cnh6|設立經濟特區|人民公社、中共加入聯合國、一胎化政策都不是外資大量進入的原因|外資進入而非撤出；深圳等沿海城市快速發展；對外出口增加
cnh6|二戰後美國占領日本|韓戰在新憲法制定之後；日本經濟泡沫化是一九九〇年代；東京奧運是一九六四年；都不是新憲法制定的原因|新憲法下天皇成為國家象徵，沒有恢復專制；憲法規定放棄戰爭；日本沒有成為共產國家
