law8|訴願|不服法院判決時，向上級法院請求重新審理;對公務員違法失職向監察院提出檢舉;人民向立法委員反映施政意見|不服法院判決向上級法院請求是上訴；向監察院檢舉公務員是陳情或檢舉；向立委反映是陳情；訴願是不服行政處分時向有管轄權的機關請求審查
law8|行政訴訟|人民之間發生財產糾紛時，向地方法院請求判決;檢察官對犯罪嫌疑人提起公訴;向鄉鎮市調解委員會申請調解|人民之間的財產糾紛是民事訴訟；檢察官起訴是刑事訴訟；申請調解是訴訟外的解決方式；行政訴訟是與行政機關的公法爭議向行政法院請求救濟
