law8|陳情|依法向行政法院提起訴訟;公務員對長官的命令提出異議;立法委員在議會詢問官員|向行政法院提起訴訟是行政訴訟；公務員對長官命令提出異議是內部程序；立委在議會詢問官員是質詢；陳情是人民向機關反映意見或建議
law8|行政處分|立法院通過的法律案;法院對案件作出的判決;行政機關內部的工作分配|立法院通過的是法律；法院作出的是判決；機關內部的工作分配不直接影響人民權利；行政處分是行政機關對外作成、直接影響人民權利義務的決定
law8|行政罰|違反契約時應付給對方的損害賠償;學校對違規學生的記過處分;鄰居之間協議的補償金|違約的損害賠償是民事責任；學校記過是校規處分；鄰居協議的補償金是私人約定；行政罰是對違反行政法上義務的處罰，例如罰鍰
