eco4|團結權|勞工個人與雇主談判薪資的權利;雇主組成同業公會的權利;勞工可以隨時離職的權利|個人與雇主談判不是集體權利；雇主組成同業公會不是勞工的團結權；隨時離職屬於工作自由；團結權是勞工組織與參加工會的權利
