eco4|童工|未滿十二歲、在家幫忙做家事的孩子;十六歲以上未滿十八歲的受僱者;已滿十八歲、第一次工作的新進員工|在家幫忙家事不是受僱；十六歲以上未滿十八歲是未成年工；已滿十八歲是成年勞工；童工依《勞動基準法》是十五歲以上未滿十六歲的受僱者
eco4|最低工資|企業依獲利發給員工的年終獎金;勞工與雇主自由約定、沒有下限的工資;政府規定所有勞工都領相同的薪水|年終獎金依獲利發給，不是最低工資；最低工資有法定下限，不是自由約定；也不是規定所有人領相同薪水；最低工資是工資不得低於政府公告的金額
eco4|勞工保險|由勞工自行購買的商業人壽保險;政府發給低收入戶的生活補助;企業為保護設備投保的火災保險|自行購買的是商業保險；給低收入戶的是社會救助；企業為設備投保的是財產保險；勞工保險是勞工發生傷病、老年等情況時的社會保險
eco4|職業災害|勞工下班後私人旅遊時受傷;企業因經營不善而倒閉;工廠機器因老舊而故障|下班後私人旅遊受傷與工作無關；企業倒閉、機器故障不是勞工受傷；職業災害是勞工因工作而受傷、生病或死亡
eco4|就業平等|所有勞工的薪水都必須相同;雇主可以依年齡優先錄取年輕人;只有女性才能申請育嬰假|就業平等不是所有人薪水相同；雇主不能因年齡歧視求職者；育嬰假男女都可以申請；就業平等是不因性別、種族等因素在就業上受到歧視
eco5|公共財|只要是政府提供的財貨就是公共財;必須付費才能使用的財貨;數量有限、先搶先贏的財貨|政府提供的不一定是公共財；必須付費、先搶先贏都是可以排除他人的特性；公共財是多人可同時使用、難以排除他人使用的財貨
eco5|私有財|可以排除他人使用，但一人使用不會減少他人可用數量的財貨;難以排除他人使用，但一人使用會減少他人可用數量的財貨;難以排除他人使用，且一人使用不會減少他人可用數量的財貨|可以排除他人、但不會減少他人可用數量的，例如付費的有線電視；難以排除他人、但會減少他人可用數量的是共有財，例如公海的魚；難以排除他人、也不會減少他人可用數量的是公共財，例如國防；私有財同時具有「可以排除他人使用」與「一人使用會減少他人可用數量」兩種特性
eco5|外部成本|企業生產商品所付出的原料費用;消費者購買商品時支付的價格;政府對污染工廠收取的罰款|原料費、商品售價都是交易雙方自己負擔的成本；政府收的罰款是改善外部成本的手段；外部成本是行為使旁人受損卻未負擔代價
eco5|外部效益|企業販售商品獲得的利潤;消費者購買商品時得到的折扣;行為人因幫助他人而獲得的報酬|企業利潤、消費折扣都是交易雙方自己得到的好處；行為人因幫忙而得到的報酬是私人利益，並沒有描述第三人得到的好處；外部效益是行為使旁人受益卻未獲得報酬
eco5|直接稅|隨商品價格一起由消費者支付的稅;政府向進口商品課徵的關稅;使用公共服務時繳交的規費|隨商品價格由消費者支付的是間接稅；關稅通常轉嫁到售價；規費是使用服務的費用，不是稅；直接稅由納稅人自己負擔、無法轉嫁
eco5|間接稅|依個人所得多寡直接課徵的稅;違規時繳交的罰鍰;向政府申請證件時繳交的規費|依個人所得直接課徵的所得稅是直接稅；罰鍰是處罰；規費是使用服務的費用；間接稅可以轉嫁給他人負擔，例如營業稅
eco5|累進稅率|每個人不論所得都繳相同金額的稅;所得越高、稅率越低的課稅方式;依商品價格固定比例課徵的稅|每人繳相同金額是定額稅；所得越高稅率越低是累退；依價格固定比例課稅是比例稅；累進稅率是所得越高、稅率越高
eco5|社會福利|企業提供給員工的福利;民間慈善團體的募款活動;政府向人民課稅以支應國防|企業給員工的是員工福利；慈善團體的募款是民間行為；國防支出不是照顧人民基本生活；社會福利是政府照顧人民基本生活的措施
