eco5|政府預算|政府已經花完的實際支出紀錄;企業年度的營收計畫;政府向人民借款發行的債券|已經花完的實際支出紀錄是決算；企業的營收計畫不是政府預算；向人民借款的是公債；政府預算是政府對一年收入與支出的計畫
soc3|核心家庭|祖父母、父母與叔伯等多房親戚同住;只有未婚兄弟姊妹同住，沒有父母同住;子女由社福機構安排到其他家庭照顧|祖父母、父母與多房親戚同住是大家庭；只有兄弟姊妹同住、子女由機構安排寄養，都不是核心家庭；核心家庭是父母與未婚子女組成
