soc3|隔代教養家庭|子女白天由保母照顧;子女暫時寄住在社福機構;祖父母每逢過年才與孫子女團聚|白天由保母照顧、暫住社福機構，都不是由祖父母長期照顧；過年才團聚也不是隔代教養；隔代教養家庭由祖父母照顧孫子女
soc3|頂客族家庭|夫妻一方工作、一方照顧子女;單身獨居、不打算結婚;夫妻收養子女共同生活|一方工作、一方照顧子女有子女；單身獨居不是夫妻家庭；收養子女就不是頂客族；頂客族家庭是夫妻都有收入、沒有子女
soc3|新住民家庭|原住民族的家庭;全家移民到國外的臺灣家庭;父母都在外縣市工作的家庭|原住民族家庭、移民國外的臺灣家庭、父母在外縣市工作的家庭都不是新住民家庭；新住民家庭是父母一方從其他國家或地區移居臺灣
soc3|生育功能|政府發放生育補助;醫院提供產前檢查;學校實施性別平等教育|其他選項是政府、醫院或學校的作為，不是家庭本身的功能
soc3|教育功能|補習班替學生加強課業;政府制定教育政策;社區圖書館舉辦說故事活動|其他選項是補習班、政府或社區的作為，不是家庭本身的功能
soc3|經濟功能|銀行提供房屋貸款;政府發放失業補助;公司按月發薪水給員工|其他選項是銀行、政府或公司的作為，不是家庭本身的功能
soc3|情感功能|輔導室老師提供學生諮商;網友在社群上按讚留言;社區舉辦聯誼活動|其他選項是學校、網路或社區提供的支持，不是家庭本身的功能
soc3|保護功能|警察巡邏維護社區治安;醫院照顧住院病人;長照機構照顧失能長者|其他選項是警察、醫院或照顧機構的作為，不是家庭本身的功能
soc3|休閒功能|公司舉辦員工旅遊;學校舉辦校外教學;社區舉辦運動會|其他選項是公司、學校或社區辦的活動，不是家庭本身的功能
law2|總統|擔任立法院院長、主持院會;任命所有法官並指揮審判;主持行政院會議、編列各部會預算|立法院院長主持院會；法官依法獨立審判，不受總統指揮；行政院院長主持行政院會議、編列預算；總統是國家元首，統率全國陸海空軍
law2|行政院|制定與修改憲法;選舉總統與副總統;審判行政訴訟案件|修憲須經立法院提案、公民複決；總統由人民直選；行政訴訟由行政法院審判；行政院是國家最高行政機關
law2|立法院|任命行政院院長;公布法律並發布命令;指揮國軍作戰|任命行政院院長的是總統；公布法律的是總統；指揮國軍作戰的是總統；立法院審議法律案與預算案、監督行政院
law2|司法院|制定民法與刑法;指揮警察偵查犯罪;監督地方政府施政|制定民法與刑法的是立法院；指揮警察偵查犯罪的是檢察官；監督地方政府施政主要是地方議會與上級機關；司法院掌理審判與解釋憲法等司法權
law2|考試院|舉辦大學學測與國中會考;制定全國教育政策;負責公務員的懲戒審判|大學學測與國中會考由專責考試機構辦理，不是考試院；制定教育政策的是教育部；公務員懲戒由懲戒法院審理；考試院掌理公務人員的考試與銓敘
law2|監察院|審理公務員的刑事案件;舉辦公職人員選舉;罷免不適任的民選首長|審理刑事案件的是法院；辦理選舉的是中央選舉委員會；罷免民選首長由選民投票；監察院行使彈劾、糾舉與審計權
law2|權力分立|中央與地方政府平均分配預算;權力集中於總統以提高效率;政黨輪流執政|中央與地方分配預算是財政問題；權力集中於總統正好與權力分立相反；政黨輪流執政是選舉結果；權力分立是把國家權力分給不同機關、互相制衡
law2|立法權|人民選舉民意代表的權力;政府徵收稅金的權力;總統任命官員的權力|選舉民意代表是選舉權；徵收稅金是行政權的一部分；任命官員是行政權；立法權是制定法律的權力
law2|行政權|人民集會遊行的權力;監察院彈劾官員的權力;人民申請公民投票的權力|集會遊行是人民的自由；彈劾官員是監察權；申請公民投票是人民的參政權；行政權是執行法律、推動政策的權力
law2|司法權|警察維持治安的權力;地方議會審議預算的權力;總統發布緊急命令的權力|警察維持治安屬於行政權；地方議會審議預算屬於地方立法權；總統發布緊急命令屬於行政權；司法權是依法審判、解決紛爭的權力
law2|彈劾|人民投票讓民選官員去職;行政院院長要求部長辭職;法院判處公務員刑罰|人民投票讓民選官員去職是罷免；院長要求部長辭職是行政內部人事；法院判刑是司法審判；彈劾是監察院對違法失職官員提出追究
law2|質詢|人民向機關陳情表達意見;監察委員調查官員是否違法;記者訪問官員施政情形|人民向機關表達意見是陳情；監察委員調查官員是監察權；記者訪問不具法律效力；質詢是立法委員詢問行政官員施政情形
law2|覆議|總統要求大法官重新解釋憲法;立法院要求行政院重新編列預算;人民對法律提出公民投票|總統不能要求大法官重新解釋；立法院要求重新編列預算不是覆議；人民對法律投票是公民投票；覆議是行政院請立法院重新審議窒礙難行的法案
law2|不信任案|人民連署罷免立法委員;總統下令解散行政院;立法委員要求院長到院報告|人民連署罷免立法委員是罷免；總統不能下令解散行政院；要求院長到院報告是邀請報告；不信任案是立法院對行政院院長表示不信任
law2|大法官|審理民事與刑事案件的一般法官;負責起訴犯罪的檢察官;立法院負責審查法案的委員|審理民事與刑事案件的是一般法官；負責起訴的是檢察官；審查法案的是立法委員；大法官審理憲法案件
eco2|需求法則|其他條件不變下，價格上漲時需求量增加;所得增加時，商品價格一定下跌;商品價格由政府決定的原則|價格上漲時需求量會減少，不是增加；所得增加不一定使價格下跌；價格由政府決定不是市場法則；需求法則是其他條件不變下，價格上漲則需求量減少
eco2|供給法則|其他條件不變下，價格上漲時供給量減少;廠商生產越多，價格一定越高;政府規定廠商產量的原則|價格上漲時供給量會增加，不是減少；生產越多不代表價格越高；政府規定產量不是市場法則；供給法則是其他條件不變下，價格上漲則供給量增加
eco2|均衡價格|政府規定的商品最高價格;廠商希望賣到的最高價格;消費者願意支付的最低價格|政府規定的最高價格是價格上限；廠商希望的最高價、消費者願付的價格都只是一方的想法；均衡價格是需求量等於供給量時的價格
eco2|替代品|價格相同的兩種商品;同一家公司生產的商品;外觀相似但用途不同的商品|價格相同、同一家公司生產、外觀相似都不代表可以互相取代；替代品是功能相近、可以互相取代的商品，例如咖啡與茶
eco2|互補品|品牌相同的商品;在同一家店販售的商品;價格總是一起上漲的商品|品牌相同、在同一家店販售、價格一起上漲都不代表要一起使用；互補品是需要一起使用的商品，例如汽車與汽油
eco2|超額需求|商品需求增加時，價格一定下跌;消費者的存款多於商品總價值;政府要求消費者增加購買|需求增加時價格通常上漲，不是下跌；存款多寡、政府要求購買都不是超額需求；超額需求是需求量大於供給量、供不應求
eco2|超額供給|廠商的庫存剛好全部賣完;政府增加商品進口配額;生產成本上升使產量減少|庫存剛好賣完是市場均衡；增加進口配額、成本上升使產量減少都不是超額供給；超額供給是供給量大於需求量、供過於求
