qpe|隘丁|清代無家無業的單身男性;取得墾照、收取大租的業主;清代負責收稅的地方官吏|無家無業的單身男性是羅漢腳；取得墾照、收取大租的是大租戶；負責收稅的是官府吏員；隘丁是守衛山區隘口的人員
