wdh1|十二銅表法|兩河流域刻在石柱上的法典;東羅馬帝國整理的羅馬法典;雅典的民主改革法令|兩河流域刻在石柱上的是漢摩拉比法典；東羅馬帝國整理的是查士丁尼的民法大全；雅典的民主改革法令也不是；十二銅表法是羅馬共和早期公布的成文法
