wdh1|楔形文字|古埃及以圖形表意的文字;腓尼基人創造的拼音字母;中國商朝刻在龜甲上的文字|古埃及以圖形表意的是象形文字；腓尼基人發展的是拼音字母；中國商朝刻在龜甲上的是甲骨文；楔形文字是兩河流域刻在泥板上的文字
wdh1|象形文字|兩河流域刻在泥板上的文字;腓尼基人創造的拼音字母;中國商朝刻在龜甲上的文字|兩河流域刻在泥板上的是楔形文字；腓尼基人發展的是拼音字母；中國商朝刻在龜甲上的是甲骨文；象形文字是古埃及以圖形表意的文字
