cnh6|越戰|朝鮮半島南北雙方與各自支持的國家交戰;國共雙方爭奪中國政權的戰爭;美蘇因部署飛彈而瀕臨核戰的危機|朝鮮半島南北交戰的是韓戰；國共爭奪中國政權的是國共內戰；美蘇因部署飛彈瀕臨核戰的是古巴飛彈危機；越戰是美國介入越南南北對立的戰爭
