twg1|緯線|連接南北兩極、表示東西位置的線;經度零度、通過英國格林威治的經線;標示地圖方向的符號|連接南北兩極、表示東西位置的是經線；經度零度的是本初子午線；標示地圖方向的是方位標；緯線與赤道平行，表示南北位置
