twg4|拉力|使人想離開原居地的因素;阻止人遷移的距離或費用等障礙;政府補助人民返鄉的措施|使人想離開原居地的是推力；阻礙遷移的距離或費用是中間障礙；補助返鄉的措施也不是拉力的定義；拉力是吸引人遷入某地的因素
