law3|政黨|為公益、文化等目的組成的社會團體;以賺取利潤為主要目的的組織;由政府設立、執行公權力的機關|為公益、文化等目的組成的是社會團體；以賺取利潤為目的的是營利組織；執行公權力的是政府機關；政黨是理念相近的人為取得政權而組成的團體
