law3|在野黨|取得政權、負責執政的政黨;負責辦理選舉事務的機關;由人民選出、監督政府的民意代表|取得政權、負責執政的是執政黨；辦理選舉事務的是中央選舉委員會；民選監督政府的是民意代表；在野黨是未執政、監督執政黨的政黨
law3|賄選|選民投票內容不被他人知道;候選人公開發表政見;政黨提名候選人參選|投票內容不被他人知道是秘密投票；公開發表政見與政黨提名都是合法的選舉活動；賄選是以金錢或利益交換選票，屬於違法行為
law4|統籌分配稅款|地方政府自行課徵的稅收;中央政府向人民借款發行的公債;人民繳給中央的所得稅|地方政府自行課徵的是地方稅；向人民借款發行的是公債；所得稅是國稅的一種；統籌分配稅款是由中央統一分配給地方的稅收
