law4|自治條例|經立法院通過、總統公布的法律;行政院依法發布的命令;村里民大會訂定的公約|經立法院通過、總統公布的是法律；行政院發布的是命令；村里民大會訂定的是公約；自治條例是經地方議會通過的地方法規
law5|法律保留原則|命令不得牴觸憲法與法律;犯罪與刑罰都必須由法律事先明定;限制人民權利時，手段必須適當且必要|命令不得牴觸憲法與法律是法律優位原則；犯罪與刑罰須事先明定是罪刑法定主義；手段須適當且必要是比例原則；法律保留原則是限制人民權利的重要事項須以法律規定
law5|法律優位原則|限制人民權利的重要事項必須以法律規定;犯罪與刑罰都必須由法律事先明定;限制人民權利時，手段必須適當且必要|限制人民權利須以法律規定是法律保留原則；犯罪與刑罰須事先明定是罪刑法定主義；手段須適當且必要是比例原則；法律優位原則是命令不得牴觸憲法與法律
law5|三讀|總統將立法院通過的法律公告周知的程序;行政院將法律案送交立法院的程序;行政院請立法院重新審議法律案的程序|總統公告周知是公布；行政院送交法律案是提案；請立法院重新審議是覆議；三讀是法律案在立法院審議的程序
law5|公布|法律案在立法院審議的程序;行政院將法律案送交立法院的程序;行政院請立法院重新審議法律案的程序|立法院審議的程序是三讀；行政院送交法律案是提案；請立法院重新審議是覆議；公布是總統將立法院通過的法律公告周知
law5|憲法|行政機關依法發布的規範;經立法院通過、總統公布的規範;地方議會通過的自治法規|行政機關依法發布的是命令；經立法院通過、總統公布的是法律；地方議會通過的是自治條例；憲法是國家根本大法，位階最高
law5|法律|國家根本大法，位階最高;行政機關依法發布的規範;地方議會通過的自治法規|國家根本大法是憲法；行政機關依法發布的是命令；地方議會通過的是自治條例；法律經立法院通過、總統公布
law5|命令|國家根本大法，位階最高;經立法院通過、總統公布的規範;地方議會通過的自治法規|國家根本大法是憲法；經立法院通過、總統公布的是法律；地方議會通過的是自治條例；命令是行政機關依法發布的規範
law6|權利能力|能獨立做出有效法律行為的能力;承擔刑事責任的能力;參與選舉投票的資格|能獨立做出有效法律行為的是行為能力；承擔刑事責任的是責任能力；投票的資格是選舉權；權利能力是享受權利、負擔義務的資格，人一出生就有
law6|行為能力|享受權利、負擔義務的資格;承擔刑事責任的能力;參與選舉投票的資格|享受權利、負擔義務的資格是權利能力；承擔刑事責任的是責任能力；投票的資格是選舉權；行為能力是能獨立做出有效法律行為的能力
law6|無行為能力人|七歲以上未滿十八歲的人;年滿十八歲、未受監護宣告的人;年滿六十五歲的老年人|七歲以上未滿十八歲的是限制行為能力人；年滿十八歲、未受監護宣告的是完全行為能力人；年滿六十五歲不會因此失去行為能力；無行為能力人是未滿七歲或受監護宣告的人
law6|限制行為能力人|未滿七歲的人，或受監護宣告的人;年滿十八歲、未受監護宣告的人;年滿六十五歲的老年人|未滿七歲或受監護宣告的是無行為能力人；年滿十八歲、未受監護宣告的是完全行為能力人；年滿六十五歲不影響行為能力；限制行為能力人是七歲以上未滿十八歲的人
law6|完全行為能力人|未滿七歲的人，或受監護宣告的人;七歲以上未滿十八歲的人;年滿二十歲且已結婚的人|未滿七歲或受監護宣告的是無行為能力人；七歲以上未滿十八歲的是限制行為能力人；民法成年已下修為十八歲，不再以二十歲或結婚為標準；完全行為能力人是年滿十八歲、未受監護宣告的人
law6|法定代理人|受當事人委託出庭的律師;七歲以上未滿十八歲的人;學生的班級導師|受委託出庭的是訴訟代理人或律師；七歲以上未滿十八歲的人是限制行為能力人；班級導師不是法定代理人；法定代理人依法代理未成年人，通常是父母
law7|無罪推定原則|犯罪與刑罰須由法律事先明定;被告必須自行證明自己無罪;犯罪嫌疑人一經起訴就推定有罪|犯罪與刑罰須事先明定是罪刑法定主義；舉證責任在檢察官，被告不必自證無罪；起訴不等於有罪；無罪推定原則是判決確定有罪前推定為無罪
law7|告訴乃論罪|不需告訴，國家就會主動追訴的犯罪;只處以罰鍰的行政違規行為;私人之間的民事糾紛|國家主動追訴的是非告訴乃論罪；只處以罰鍰的是行政罰；私人之間的糾紛是民事糾紛；告訴乃論罪須由有告訴權的人提出告訴才會追究
law7|非告訴乃論罪|須由有告訴權的人提出告訴，才會追究的犯罪;只處以罰鍰的行政違規行為;私人之間的民事糾紛|須有告訴權的人提告才追究的是告訴乃論罪；只處以罰鍰的是行政罰；私人之間的糾紛是民事糾紛；非告訴乃論罪不需告訴，國家就會主動追訴
law7|檢察官|依法審判、做出判決;在刑事訴訟中協助被告的律師;維持治安、協助偵查的警察|依法審判的是法官；協助被告的是辯護人；維持治安、協助偵查的是警察；檢察官代表國家偵查犯罪、提起公訴
law7|法官|代表國家偵查犯罪、提起公訴;在刑事訴訟中協助被告的律師;維持治安、協助偵查的警察|偵查犯罪、提起公訴的是檢察官；協助被告的是辯護人；維持治安的是警察；法官依法審判、做出判決
law7|辯護人|代表國家偵查犯罪、提起公訴;依法審判、做出判決;維持治安、協助偵查的警察|偵查犯罪、提起公訴的是檢察官；依法審判的是法官；維持治安的是警察；辯護人在刑事訴訟中協助被告
law7|少年事件處理法|規定犯罪與刑罰的一般法律;規範人民之間權利義務的法律;規定學校管教方式的校規|規定犯罪與刑罰的一般法律是刑法，刑法並非只適用成年人；規範人民權利義務的是民法；學校管教依校規；少年事件處理法是針對少年的特別法，重視保護與教育，處理的少年事件分為保護事件與刑事案件，也包括有觸法之虞的曝險少年
law7|保護管束|將少年安置於矯正學校接受教育的保護處分;把少年關進監獄服刑;由法院判處少年繳納罰金|安置於矯正學校的是感化教育；少年事件以保護教育為主，原則上不送監獄服刑或判罰金；保護管束是讓少年在社會中接受輔導與監督
law7|感化教育|少年在社會中接受輔導與監督的保護處分;把少年關進監獄服刑;由法院判處少年繳納罰金|在社會中接受輔導監督的是保護管束；少年事件以保護教育為主，原則上不送監獄服刑或判罰金；感化教育是將少年安置於矯正學校接受教育
eco1|財貨|能滿足人類慾望的無形服務;交易時使用的貨幣;人們做選擇時放棄的價值|無形的服務是勞務；交易媒介是貨幣；做選擇時放棄的價值是機會成本；財貨是能滿足人類慾望的有形物品
eco1|自由財|能滿足人類慾望的無形服務;具有稀少性、需付出代價取得的財貨;政府免費提供的公共設施|無形的服務是勞務；具有稀少性、需付出代價的是經濟財；政府提供的公共設施仍要花費資源，不是自由財；自由財取之不盡、不需付費，例如空氣
eco1|經濟財|取之不盡、不需付費的資源，例如空氣;能滿足人類慾望的無形服務;政府免費提供的公共設施|取之不盡、不需付費的是自由財；無形的服務是勞務；政府提供的公共設施仍需成本，屬於經濟財，但定義不是「免費提供」；經濟財具有稀少性、需付出代價取得
eco3|以物易物|用貨幣購買商品;透過網路平台拍賣商品;把商品寄放在店家代售|用貨幣購買是貨幣交易；網路拍賣、寄賣都需要用錢交易；以物易物是直接用物品交換物品
eco3|通貨膨脹|物價全面持續下跌;少數商品價格短暫上漲;貨幣購買力持續提高|物價全面持續下跌是通貨緊縮；少數商品短暫上漲不算通膨；通膨時貨幣購買力下降，不是提高；通貨膨脹是物價全面持續上漲
eco3|通貨緊縮|物價全面持續上漲;少數商品因促銷而短暫降價;貨幣購買力持續下降|物價全面持續上漲是通貨膨脹；少數商品促銷降價不算通縮；通縮時貨幣購買力上升，不是下降；通貨緊縮是物價全面持續下跌
eco3|中央銀行|吸收存款、辦理放款的金融機構;負責編列政府預算的機關;管理股票交易的市場|吸收存款、辦理放款的是商業銀行；編列政府預算的是行政院主計總處；管理股票交易的是證券交易所；中央銀行發行貨幣、制定貨幣政策
eco3|商業銀行|發行貨幣、制定貨幣政策的機關;負責編列政府預算的機關;管理股票交易的市場|發行貨幣、制定貨幣政策的是中央銀行；編列政府預算的是主計總處；管理股票交易的是證券交易所；商業銀行吸收存款、辦理放款
eco3|利息|利息占本金的比例;把所得中未消費的部分保存起來;借款人向銀行借入的本金|利息占本金的比例是利率；保存未消費的所得是儲蓄；借入的本金是借款本身；利息是借用金錢所支付的報酬
eco3|利率|把所得中未消費的部分保存起來;借用金錢所支付的報酬;物價上漲的幅度|保存未消費的所得是儲蓄；借用金錢的報酬是利息；物價上漲的幅度是通膨率；利率是利息占本金的比例
eco3|儲蓄|借用金錢所支付的報酬;利息占本金的比例;把錢花在購買商品與服務|借用金錢的報酬是利息；利息占本金的比例是利率；把錢花在商品與服務是消費；儲蓄是把所得中未消費的部分保存起來
eco3|股票|政府或企業向大眾借錢所發行的憑證;存在銀行、約定期限的存款;共同集資、委由專人投資的基金|向大眾借錢發行的憑證是債券；約定期限的存款是定期存款；集資委託專人投資的是基金；股票代表擁有部分公司所有權
eco3|債券|公司發行、代表擁有部分公司所有權的證明;存在銀行、約定期限的存款;共同集資、委由專人投資的基金|代表公司所有權的是股票；約定期限的存款是定期存款；集資委託專人投資的是基金；債券是政府或企業向大眾借錢發行的憑證
eco3|信用卡|在存款餘額內直接扣款的支付工具;預先儲值後使用的支付工具;以現金完成的付款方式|在存款餘額內扣款的是金融卡；預先儲值的是儲值卡；以現金付款不需卡片；信用卡是先消費、後付款的支付工具
eco3|電子支付|以現金完成的付款方式;以支票完成的付款方式;到郵局以匯票付款|現金、支票與郵局匯票都是傳統的付款方式；電子支付是透過電子方式完成付款
voy|熱蘭遮城|荷蘭人在赤崁興建的城堡，今赤崁樓前身;西班牙人在淡水興建的城堡;西班牙人在雞籠興建的城堡|荷蘭人在赤崁興建的是普羅民遮城；西班牙人在淡水興建的是聖多明哥城，在雞籠興建的是聖薩爾瓦多城
voy|聖薩爾瓦多城|荷蘭人在大員興建的統治中心城堡;荷蘭人在赤崁興建的城堡，今赤崁樓前身;西班牙人在淡水興建的城堡|荷蘭人在大員興建的是熱蘭遮城，在赤崁興建的是普羅民遮城；西班牙人在淡水興建的是聖多明哥城
voy|聖多明哥城|荷蘭人在大員興建的統治中心城堡;西班牙人在雞籠興建的城堡;荷蘭人在赤崁興建的城堡，今赤崁樓前身|荷蘭人在大員興建的是熱蘭遮城，在赤崁興建的是普羅民遮城；西班牙人在雞籠興建的是聖薩爾瓦多城
voy|東寧|清廷收臺後設立的臺灣府;明代文獻對臺灣的稱呼「東番」;葡萄牙人對臺灣的稱呼「福爾摩沙」|清廷收臺後設立的是臺灣府；明代文獻稱臺灣為「東番」；「福爾摩沙」是葡萄牙人對臺灣的稱呼；「東寧」則是鄭經時期對臺灣的稱呼
voy|王田|鄭氏軍隊屯墾開發的營盤田;清代墾戶申請墾照開墾的土地;原住民部落共有的獵場|鄭氏軍隊屯墾開發的是營盤田；清代墾戶申請墾照開墾的是私人墾地；原住民部落共有的獵場也不是王田；王田是荷蘭時期名義上屬於東印度公司的土地
voy|贌社|荷蘭人向漢人收取的人頭稅;荷蘭人把公司土地交給漢人耕作;鄭氏政權獨占對日本的貿易|人頭稅是荷蘭人向漢人收取的稅；把公司土地交給漢人耕作的是王田制度；鄭氏政權的對外貿易也不是贌社；贌社是把與原住民交易的權利承包給商人
voy|新港文書|以漢字書寫的清代土地契約;荷蘭人記錄統治事務的日誌;鄭氏政權頒布的開墾告示|以漢字書寫的清代土地契約是一般漢文契約；荷蘭人記錄統治事務的是熱蘭遮城日誌；鄭氏的開墾告示也不是新港文書；新港文書是以羅馬拼音書寫西拉雅語的契約
voy|屯田|荷蘭人招募漢人開墾公司土地;清代墾戶申請墾照開墾;原住民部落以游耕方式耕作|荷蘭人招募漢人開墾的是王田；清代墾戶申請墾照開墾是民間拓墾；原住民的游耕是傳統耕作方式；屯田是鄭氏軍隊一邊駐守一邊開墾
voy|承天府|荷蘭人在大員的統治中心;清廷收臺後設立的臺灣府;西班牙人在雞籠的統治據點|荷蘭人在大員的統治中心是熱蘭遮城；清廷收臺後設立的是臺灣府；西班牙人在雞籠的據點是聖薩爾瓦多城；承天府是鄭成功設立的最高行政機構
voy|地方會議|鄭氏政權召開的軍事會議;清代官府主持的鄉約宣講;漢人移民組成的同鄉會館|地方會議不是鄭氏的軍事會議，也不是清代的鄉約宣講或漢人的同鄉會館；它是荷蘭人召集各部落長老、宣示統治的集會
voy|遷界令|清初限制人民渡海來臺的規定;明朝禁止人民出海貿易的海禁;荷蘭人禁止漢人進入原住民部落的命令|限制人民渡海來臺的是渡臺禁令；禁止人民出海貿易的是明朝的海禁；荷蘭人並未以遷界令管理原住民部落；遷界令是清廷命沿海居民內遷、切斷對鄭氏的接濟
qpe|郊|開港後外國商人設立的貿易商行;清代地方士紳講學的書院;同鄉移民集會祭祀的會館|開港後外國商人設立的是洋行；地方士紳講學的是書院；同鄉移民集會祭祀的是會館；郊是清代同類商品或同一地區貿易的商人組成的商業團體
qpe|洋行|清代從事同類商品或同一地區貿易的商人組成的商業團體;清代官府經營的鹽館;清代經營存放款的錢莊|同類商品或同一地區貿易的商人組成的是郊；官府經營的鹽館與經營存放款的錢莊都不是洋行；洋行是開港後外國商人在臺灣設立的貿易商行
qpe|對渡|開港後開放外國商船進出臺灣港口;清初禁止人民渡海來臺;鄭氏政權與日本之間的貿易航線|開放外國商船進出是清末的開港通商；禁止人民渡海來臺是渡臺禁令；鄭氏與日本的貿易也不是對渡；對渡是清廷指定臺灣與大陸港口直接往來
qpe|一府二鹿三艋舺|清代臺灣的三個行政區;開港後外國商人設立的三大洋行;開港後開放通商的口岸|這句俗諺不是行政區、洋行或開港口岸的名稱，而是指清代最繁榮的三個港市：臺南府城、鹿港、艋舺
qpe|土牛溝|清代為防衛原住民而設置的隘寮;清代為灌溉而開鑿的水圳;清代為防禦而建的竹城|隘寮是隘丁駐守的哨所；水圳是灌溉渠道；竹城是用竹子圍成的城牆；土牛溝是劃分漢人與原住民生活範圍的土堆與溝渠
qsc|分類械鬥|民眾與教會之間的衝突;官府與民眾之間的民變;漢人與原住民之間的土地衝突|民眾與教會之間的衝突是教案；官府與民眾之間的衝突是民變；漢人與原住民的土地衝突是漢番衝突；分類械鬥是不同祖籍移民之間的衝突
qsc|教案|不同祖籍移民為爭奪資源發生的衝突;官府與民眾之間的民變;漢人與原住民之間的土地衝突|不同祖籍移民的衝突是分類械鬥；官府與民眾的衝突是民變；漢人與原住民的土地衝突是漢番衝突；教案是民眾與教會之間的衝突
qsc|土著化|平埔族改用漢姓漢語的漢化過程;移民仍以原鄉祖籍為認同的現象;日治時期要求臺灣人成為日本人的皇民化|平埔族改用漢姓漢語是漢化；仍以原鄉祖籍為認同正好與土著化相反；要求臺灣人成為日本人的是日治時期的皇民化；土著化是移民逐漸以臺灣為認同
qsc|宗族|同一祖籍移民集資興建的廟宇組織;移民為自衛組成的團練;同業商人組成的郊|同祖籍移民的廟宇組織是寺廟組織；為自衛組成的是團練；同業商人組成的是郊；宗族是以血緣為基礎、祭祀共同祖先的組織
qsc|祭祀公業|寺廟收取的香油錢;官府撥給書院的學田;移民集資修築水圳的費用|寺廟的香油錢屬於寺廟；官府撥給書院的是學田；修築水圳的費用也不是祭祀公業；祭祀公業是宗族用於祭祖的共有財產
qsc|六堆|漳州移民組成的郊商團體;官府徵調平埔族組成的屯兵;同一宗族祭祀祖先的組織|六堆不是漳州郊商、平埔族屯兵或宗族組織，而是屏東客家庄組成的自衛組織
qsc|番屯|由福建調派、三年輪換的駐臺軍隊制度;客家庄組成的自衛組織;漢人移民僱用守衛隘口的隘丁|由福建調派、三年輪換的是班兵；客家庄的自衛組織是六堆；漢人僱用守衛隘口的是隘丁；番屯是挑選平埔族人駐守邊界的制度
jpe|六三法|規定臺灣人享有與日本人同等權利的法律;規定臺灣直接適用日本憲法的法律;規定臺灣人可選舉議員的法律|六三法沒有讓臺灣人享有與日本人同等的權利，也沒有讓臺灣直接適用日本憲法或選舉議員；它賦予總督發布具法律效力命令的權力
jpe|保甲制度|由日本警察負責全部治安、不需民眾參與;讓臺灣人選出地方議員的制度;以武力控制山地原住民的計畫|保甲制度要求民眾參與、鄰里連坐，不是只靠警察；選出地方議員是地方自治；以武力控制山地原住民的是理蕃計畫
jpe|專賣制度|政府清查土地以增加田賦;開放民間自由買賣鴉片、樟腦;政府向進口商品課徵關稅|清查土地增加田賦的是土地調查；專賣是政府獨占經營，不是開放民間自由買賣；向進口商品課稅的是關稅
jpe|內地延長主義|要求臺灣人成為天皇子民的運動;依臺灣特殊情況另訂制度的特別統治;以臺灣為向南洋擴張的基地|要求臺灣人成為天皇子民的是皇民化運動；依臺灣特殊情況另訂制度的是特別統治主義；以臺灣為向南洋擴張基地的是南進政策
jpe|皇民化運動|把日本本土制度延伸到臺灣的同化方針;依臺灣特殊情況另訂制度的特別統治;鼓勵臺灣人保存傳統漢文化的運動|把日本本土制度延伸到臺灣的是內地延長主義；依臺灣特殊情況另訂制度的是特別統治主義；皇民化運動要求改用日語、改日本姓名，並不鼓勵保存漢文化
jpe|南進政策|以臺灣發展農業、供應日本糧食;以臺灣為向北方擴張的基地;日本放棄海外擴張、專注本土建設|以臺灣發展農業、供應日本糧食是「工業日本、農業臺灣」；南進政策是向南洋擴張，不是向北方；日本當時並未放棄海外擴張
jpe|工業日本、農業臺灣|日治後期在臺灣發展軍需工業;臺灣與日本都以農業為主;臺灣發展工業、日本發展農業|在臺灣發展軍需工業是日治後期南進政策時的轉變；日本本身以工業為主；正確分工是日本發展工業、臺灣發展農業，不是相反
jsc|國語家庭|全家改用日本姓名的家庭;家中供奉日本神宮大麻的家庭;子女都進入公學校就讀的家庭|改用日本姓名是改姓名運動；供奉神宮大麻是正廳改善；子女進入公學校就讀不等於國語家庭；國語家庭是全家使用日語而受表揚的家庭
jsc|寺廟整理|鼓勵在家中供奉日本神宮大麻;要求臺灣人改用日本姓名;禁止演出傳統戲曲|供奉神宮大麻是正廳改善；改用日本姓名是改姓名運動；禁止傳統戲曲是另一項皇民化措施；寺廟整理是拆併傳統寺廟
jsc|白話文運動|提倡以文言文寫作古典詩詞;推廣日語的國語運動;提倡以美術展覽啟發民智|以文言文寫古典詩詞正好與白話文運動相反；推廣日語的是國語運動；美術展覽是臺展；白話文運動提倡以淺白文字書寫來啟蒙大眾
jsc|臺展|臺灣總督府舉辦的博覽會;臺灣文化協會舉辦的演講會;日本本土舉辦的帝國美術展覽|總督府舉辦的博覽會是展示產業成果；文化協會舉辦的是文化演講會；日本本土的美術展覽是帝展；臺展是在臺灣舉辦的美術展覽會
jsc|星期制|以農曆節氣安排農事的作息;以十天為一旬的作息;以干支紀日的曆法|依農曆節氣安排農事是傳統農家作息；十天一旬是傳統的計日方式；干支紀日是曆法；星期制是以七天為循環的作息制度
jsc|標準時間|以七天為循環的作息制度;各地依太陽位置自訂的地方時;以農曆節氣安排農事的作息|以七天為循環的是星期制；各地依太陽位置自訂的是地方時；依農曆節氣安排的是傳統農事作息；標準時間是統一時間、建立守時觀念的制度
jsc|天然足會|推動男子剪辮的斷髮會;啟蒙民眾的臺灣文化協會;推廣日語的國語講習所|推動男子剪辮的是斷髮會；啟蒙民眾的是臺灣文化協會；推廣日語的是國語講習所；天然足會是推動女子解纏足的社團
cnh2|絲路|經東南亞、印度洋往來的海上貿易路線;連接中國南北的大運河;連接四川、雲南與西藏的茶馬古道|經東南亞、印度洋的是海上絲路；連接中國南北的是大運河；連接四川、雲南與西藏的是茶馬古道；絲路是連接中國與中亞、西亞的陸上貿易通道
cnh2|海上絲路|連接中國與中亞、西亞的陸上貿易通道;連接中國南北的大運河;連接四川、雲南與西藏的茶馬古道|連接中國與中亞、西亞的陸上通道是絲路；連接中國南北的是大運河；連接四川、雲南與西藏的是茶馬古道；海上絲路是經東南亞、印度洋往來的海上貿易路線
cnh2|市舶司|唐代掌管外交接待的鴻臚寺;明代輔佐皇帝的內閣;清代處理軍國大事的軍機處|鴻臚寺掌管外交接待；內閣輔佐明代皇帝處理政務；軍機處處理清代軍國大事；市舶司才是唐宋以後管理海外貿易的官署
cnh2|遣唐使|日本派往隋朝的使節團;唐朝派往西域的使節團;新羅派往唐朝的朝貢使節|日本派往隋朝的是遣隋使；唐朝派往西域的使節、新羅派往唐朝的使節都不叫遣唐使；遣唐使是日本派往唐朝學習制度文化的使節團
cnh2|大化革新|日本學習西方制度的現代化改革;唐朝推行的均田制;隋朝開創的科舉制度|日本學習西方的改革是明治維新；均田制是唐朝的土地制度；科舉是隋朝開創的選官制度；大化革新是日本仿效唐朝制度進行的政治改革
cnh2|《馬可波羅遊記》|記載玄奘西行見聞的著作;東晉法顯赴天竺求法的著作;魏源介紹世界各國的著作|記載玄奘西行見聞的是《大唐西域記》；法顯赴天竺求法的是《佛國記》；魏源介紹世界各國的是《海國圖志》；《馬可波羅遊記》記述元代中國的富庶
wdh1|城邦|由皇帝統治廣大領土的帝國;由多個部落組成的游牧聯盟;由神廟祭司統治的神權國家|由皇帝統治廣大領土的是帝國；由多個部落組成的是游牧聯盟；由祭司統治的是神權國家；城邦是古希臘以城市為中心的獨立國家
wdh1|直接民主|由人民選出代表議決政事;由國王一人決定政事;由少數貴族決定政事|由人民選出代表議決政事是代議民主；由國王一人決定是君主專制；由少數貴族決定是貴族政治；直接民主是公民親自參加公民大會表決
wdh1|羅馬共和|由皇帝一人掌握大權的政體;公民親自參加公民大會表決政事的雅典民主;由國王世襲統治的君主政體|由皇帝一人掌權是羅馬帝國時期；公民親自參加公民大會表決是雅典民主；由國王世襲統治是君主政體；羅馬共和由元老院與選出的執政官治理
wdh1|種姓制度|古羅馬區分貴族與平民的制度;中國依考試成績選官的科舉制度;歐洲中古時期的封建制度|古羅馬區分貴族與平民、中國的科舉、歐洲中古的封建制度都不是種姓制度；種姓制度是印度依出身劃分階級、世代相傳的社會制度
wdh2|十字軍東征|蒙古向歐亞擴張的西征;鄂圖曼帝國攻下君士坦丁堡的戰爭;伊斯蘭教向北非與西班牙擴張的戰爭|蒙古向歐亞擴張是蒙古西征；鄂圖曼帝國攻下君士坦丁堡、伊斯蘭教向北非與西班牙擴張，都是穆斯林一方的戰爭；十字軍東征是歐洲基督徒以收復聖地為名發動的軍事行動
wdh3|人文主義|以神為中心、重視來世的思想;主張政府權力來自人民同意;主張多出口、少進口以累積金銀的思想|以神為中心、重視來世是中古時期的思想，正好與人文主義相反；主張政府權力來自人民同意的是社會契約論；主張多出口少進口的是重商主義
wdh3|贖罪券|教會向信徒徵收收入十分之一的什一稅;馬丁路德提出批評教會的論綱;教宗開除教籍的文書|向信徒徵收收入十分之一的是什一稅；馬丁路德批評教會的是《九十五條論綱》；把信徒逐出教會的是開除教籍；贖罪券是教會販售、宣稱可減輕罪罰的憑證
wdh3|社會契約論|主張國王權力來自上帝的君權神授說;主張多出口、少進口以累積金銀的思想;肯定人的價值與現世生活的思想|主張國王權力來自上帝的是君權神授說；主張多出口少進口的是重商主義；肯定人的價值與現世生活的是人文主義；社會契約論主張政府權力來自人民同意
wdh4|馬尼拉大帆船貿易|歐洲、非洲、美洲之間以奴隸為核心的貿易;中國經中亞往來的絲路貿易;荷蘭經臺灣轉運的中日貿易|歐洲、非洲、美洲之間以奴隸為核心的是三角貿易；經中亞的是絲路貿易；荷蘭經臺灣轉運的是中日轉口貿易；馬尼拉大帆船貿易是西班牙經菲律賓把美洲白銀運往亞洲
wdh6|帝國主義|主張各民族建立自己國家的民族主義;主張生產工具公有的社會主義;主張以理性批判專制的啟蒙思想|民族主義主張各民族建立自己的國家；社會主義主張生產工具公有；啟蒙思想以理性批判專制；帝國主義是強國以政治、經濟、軍事力量控制他國
wdh6|社會達爾文主義|主張各民族建立自己國家的民族主義;主張生產工具公有的社會主義;主張天賦人權、人人平等的思想|民族主義主張各民族建立自己的國家；社會主義主張生產工具公有；天賦人權、人人平等是啟蒙思想；社會達爾文主義把「適者生存」套用到國家與民族
wdh6|明治維新|中國學習西方軍事科技的自強運動;清末推動君主立憲的戊戌變法;日本仿效唐朝制度的大化革新|中國學習西方軍事科技的是自強運動；清末推動君主立憲的是戊戌變法；日本仿效唐朝的是大化革新；明治維新是日本學習西方、推動現代化的改革
wdh6|非暴力不合作|以武裝起義推翻殖民政府;請求外國出兵協助獨立;透過暗殺殖民官員爭取獨立|武裝起義、請求外國出兵、暗殺官員都是使用武力的方式，正好與甘地的主張相反；非暴力不合作是以不使用暴力的抵制方式爭取獨立
twg5|加工出口區|聚集高科技產業、重視研發的園區;以農產加工為主的農業區;提供國際貨物轉運的自由貿易港區|聚集高科技產業、重視研發的是科學園區；以農產加工為主的不是加工出口區；提供國際貨物轉運的是自由貿易港區；加工出口區進口原料、加工後外銷
twg5|產業升級|企業把工廠移往成本較低的國家或地區;由技術密集轉向勞力密集;產業由服務業退回農業|把工廠移往成本較低地區是產業外移；由技術密集轉向勞力密集、由服務業退回農業都是方向相反；產業升級是由勞力密集轉向技術與資本密集
twg5|產業群聚|產業平均分散到全國各地;企業把工廠移往成本較低的國家或地區;同一產業的廠商彼此互不往來|產業平均分散各地、廠商互不往來都與群聚相反；把工廠移往成本較低地區是產業外移；產業群聚是相關產業集中在同一地區、互相支援
twg6|一日生活圈|每天往返住家與工作或上學地點;步行十分鐘內可取得生活機能的範圍;以大城市為核心的都會區|每天往返住家與工作地點是通勤；步行可及的生活機能範圍是生活圈中的社區範圍；以大城市為核心的是都會區；一日生活圈是交通改善後一天內可往返各主要城市
twg6|區域均衡發展|集中資源發展大城市的政策;鼓勵人口移往都市的政策;限制鄉村建設的政策|集中資源發展大城市、鼓勵人口移往都市、限制鄉村建設都會擴大差距，正好與區域均衡發展相反
asg2|綠洲農業|在平原上大規模種植小麥的農業;在高原上飼養犛牛、藏羊的牧業;隨季節帶牲畜遷移的游牧|在平原大規模種植小麥是旱作農業；在高原飼養犛牛、藏羊是高原牧業；隨季節遷移放牧是游牧；綠洲農業是在沙漠中利用水源發展的定居農業
asg5|波斯灣|阿拉伯半島西側、通往蘇伊士運河的紅海;歐亞非三洲之間的地中海;世界最大的鹹水湖裏海|紅海、地中海是不同的海域，裏海是內陸鹹水湖；波斯灣位於阿拉伯半島與伊朗之間，石油蘊藏豐富
asg5|綠洲|沙漠中流動的沙丘;河川出海口堆積的三角洲;乾燥地區的鹽湖|流動的沙丘、河口三角洲、乾燥地區的鹽湖都不是綠洲；綠洲是沙漠中有水源、可以農耕的地方
asg5|撒哈拉沙漠|阿拉伯半島的沙漠;中國新疆的塔克拉瑪干沙漠;蒙古的戈壁沙漠|阿拉伯半島、新疆塔克拉瑪干、蒙古戈壁都是其他地區的沙漠；撒哈拉沙漠位於北非，面積廣大
asg5|耶路撒冷|伊斯蘭教的聖地麥加;天主教教宗所在的梵蒂岡;東正教的中心君士坦丁堡|麥加只是伊斯蘭教的聖地；梵蒂岡是天主教教宗所在地；君士坦丁堡是東正教的中心；耶路撒冷是猶太教、基督教、伊斯蘭教共同的聖地
wdg1|南極條約|要求已開發國家減少溫室氣體排放的京都議定書;限制各國捕鯨的國際公約;保護臭氧層的蒙特婁議定書|京都議定書規範已開發國家的溫室氣體減量；限制捕鯨的是國際捕鯨公約；蒙特婁議定書保護臭氧層；這三項分別處理氣候變遷、捕鯨管理與臭氧層保護，都不是專門規範南極和平利用與科學研究的條約；南極條約規定南極用於和平與科學研究
